import {DuckDBClient} from "@observablehq/duckdb"







RPG_URL = "https://minio.lab.sspcloud.fr/lgaliana/data/geodata-days/rpg_pac_2024_62_comm_v11.parquet"







db = DuckDBClient.of({ dico: dico })







// Réchauffe le fetch réseau + le cache DuckDB-wasm du parquet dès le
// chargement du deck, pour que le premier "Tester en live" mesure le temps
// de requête et non le temps de téléchargement du fichier. Sert aussi à
// afficher le nombre de lignes scannées en entrée des requêtes.
warmupRPG = db.query(`SELECT COUNT(*) AS n_input FROM read_parquet('${RPG_URL}') WHERE code_cultu IS NOT NULL`)







totalInputRows = Number(Array.from(warmupRPG)[0].n_input)







function truncateLabel(text, maxLen = 42) {
  const s = String(text ?? "");
  return s.length &gt; maxLen ? s.slice(0, maxLen - 1) + "…" : s;
}







function toggleInput(defaultValue = false) {
  const input = html`&lt;input type="checkbox" ${defaultValue ? "checked" : ""}&gt;`;
  const label = html`&lt;label style="cursor: pointer; user-select: none; font-size: 0.9em;"&gt;${input} &lt;span&gt;SQL ⇄ graphique&lt;/span&gt;&lt;/label&gt;`;
  label.value = input.checked;
  input.oninput = () =&gt; {
    label.value = input.checked;
    label.dispatchEvent(new CustomEvent("input"));
  };
  return label;
}







function sqlOrPlot(toggle, sql, plot) {
  const container = html`&lt;div&gt;&lt;/div&gt;`;
  function render() {
    container.replaceChildren(toggle.value ? html`&lt;pre&gt;&lt;code&gt;${sql}&lt;/code&gt;&lt;/pre&gt;` : plot);
  }
  render();
  toggle.addEventListener("input", render);
  return container;
}







function runLiveButton(label = "Tester en live") {
  const btn = html`&lt;button type="button" class="run-live-btn" aria-label="${label}" title="${label}"&gt;
    &lt;svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"&gt;&lt;path d="M8 5v14l11-7z"/&gt;&lt;/svg&gt;
  &lt;/button&gt;`;
  btn.value = null;
  btn.onclick = () =&gt; {
    btn.value = Date.now();
    btn.dispatchEvent(new CustomEvent("input"));
  };
  return btn;
}







function searchInput(placeholder = "Rechercher…") {
  const input = html`&lt;input type="search" class="testlive-search-input" placeholder="${placeholder}"&gt;`;
  input.value = "";
  return input;
}







function frInt(n) {
  return Number(n).toLocaleString("fr-FR");
}







function frNumber(n, decimals = 0) {
  return Number(n).toLocaleString("fr-FR", {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals
  });
}







function barCell(share, color = "#4758AB") {
  const pct = share * 100;
  return html`&lt;div class="bar-track"&gt;&lt;div class="bar-fill" style="width:${pct}%; background:${color}"&gt;&lt;/div&gt;&lt;span class="bar-label"&gt;${pct.toFixed(1)}%&lt;/span&gt;&lt;/div&gt;`;
}







function debounce(fn, ms = 300) {
  let t;
  return (...args) =&gt; {
    clearTimeout(t);
    t = setTimeout(() =&gt; fn(...args), ms);
  };
}







// Champ "commande avec autocomplétion" : on tape pour filtrer une liste
// figée (`options`), mais la valeur retenue (`.value`) est TOUJOURS soit ""
// soit une entrée exacte de la liste — jamais du texte libre. Ça garantit
// qu'on n'injecte jamais une commune inexistante dans le SQL. Émet un
// événement "input" à chaque sélection (y compris le retour à "").
function comboBox(options, { placeholder = "" } = {}) {
  // supprime les diacritiques (bloc combinant U+0300..U+036F) pour une
  // recherche tolérante aux accents ("bethune" trouve "Béthune")
  const norm = (s) =&gt;
    String(s)
      .normalize("NFD")
      .replace(/[̀-ͯ]/g, "")
      .toLowerCase()
      .trim();
  const input = html`&lt;input type="text" class="testlive-search-input" placeholder="${placeholder}"
    autocomplete="off" role="combobox" aria-expanded="false" aria-autocomplete="list"&gt;`;
  const menu = html`&lt;ul class="combo-menu" role="listbox"&gt;&lt;/ul&gt;`;
  menu.hidden = true;
  const wrap = html`&lt;div class="combo-box"&gt;${input}${menu}&lt;/div&gt;`;
  let value = "";
  let activeIdx = -1;
  wrap.value = value;

  function matches() {
    const q = norm(input.value);
    const list = !q ? options : options.filter((o) =&gt; norm(o).includes(q));
    return list.slice(0, 60);
  }

  function openMenu() {
    const list = matches();
    activeIdx = -1;
    menu.replaceChildren(
      ...list.map((o) =&gt; {
        const li = html`&lt;li role="option" data-val="${o}"&gt;${o}&lt;/li&gt;`;
        li.onmousedown = (e) =&gt; {
          e.preventDefault();
          commit(o);
        };
        return li;
      })
    );
    menu.hidden = list.length === 0;
    input.setAttribute("aria-expanded", String(!menu.hidden));
  }

  function closeMenu() {
    menu.hidden = true;
    activeIdx = -1;
    input.setAttribute("aria-expanded", "false");
  }

  function commit(o) {
    const next = o ?? "";
    input.value = next;
    closeMenu();
    if (next !== value) {
      value = next;
      wrap.value = value;
      wrap.dispatchEvent(new CustomEvent("input"));
    }
  }

  input.addEventListener("focus", () =&gt; {
    input.select(); // prêt à retaper une autre commune
    openMenu();
  });
  input.addEventListener("input", openMenu);
  input.addEventListener("blur", () =&gt; {
    // Laisse le mousedown d'un &lt;li&gt; se déclencher avant de valider.
    setTimeout(() =&gt; {
      const exact = options.find((o) =&gt; norm(o) === norm(input.value));
      if (norm(input.value) === "") commit("");
      else if (exact) commit(exact);
      else {
        input.value = value; // texte libre non reconnu -&gt; on annule
        closeMenu();
      }
    }, 150);
  });
  input.addEventListener("keydown", (e) =&gt; {
    const items = [...menu.children];
    if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault();
      if (menu.hidden) return openMenu();
      activeIdx =
        e.key === "ArrowDown"
          ? Math.min(activeIdx + 1, items.length - 1)
          : Math.max(activeIdx - 1, 0);
      items.forEach((li, i) =&gt; li.classList.toggle("active", i === activeIdx));
      if (items[activeIdx]) items[activeIdx].scrollIntoView({ block: "nearest" });
    } else if (e.key === "Enter") {
      if (activeIdx &gt;= 0 && items[activeIdx]) {
        e.preventDefault();
        commit(items[activeIdx].dataset.val);
      }
    } else if (e.key === "Escape") {
      input.value = value;
      closeMenu();
    }
  });

  return wrap;
}







// Mini coloration syntaxique SQL (pas de dépendance : highlight.js n'est pas
// chargé sur ce deck). Renvoie du HTML — les classes tok-* sont stylées en
// thème sombre dans custom.css.
function sqlHighlight(sql) {
  const KW = new Set([
    "SELECT", "FROM", "WHERE", "GROUP", "BY", "ORDER", "HAVING", "LIMIT",
    "OFFSET", "AS", "ON", "AND", "OR", "NOT", "NULL", "IS", "IN", "LIKE",
    "ILIKE", "BETWEEN", "JOIN", "LEFT", "RIGHT", "INNER", "OUTER", "FULL",
    "CROSS", "UNION", "ALL", "DISTINCT", "ASC", "DESC", "CASE", "WHEN",
    "THEN", "ELSE", "END", "USING", "WITH", "OVER", "PARTITION"
  ]);
  const esc = (s) =&gt;
    s.replace(/&/g, "&amp;").replace(/&lt;/g, "&lt;").replace(/&gt;/g, "&gt;");
  const tok = /--[^\n]*|'(?:[^']|'')*'|\b\d+(?:\.\d+)?\b|[A-Za-z_]\w*|[(),.;*=/&lt;&gt;+|!-]+/g;
  let out = "";
  let last = 0;
  let m;
  while ((m = tok.exec(sql))) {
    out += esc(sql.slice(last, m.index));
    last = tok.lastIndex;
    const t = m[0];
    if (t.startsWith("--")) out += `&lt;span class="tok-com"&gt;${esc(t)}&lt;/span&gt;`;
    else if (t.startsWith("'")) out += `&lt;span class="tok-str"&gt;${esc(t)}&lt;/span&gt;`;
    else if (/^\d/.test(t)) out += `&lt;span class="tok-num"&gt;${esc(t)}&lt;/span&gt;`;
    else if (/^[A-Za-z_]/.test(t)) {
      if (KW.has(t.toUpperCase())) out += `&lt;span class="tok-kw"&gt;${esc(t)}&lt;/span&gt;`;
      else if (/^\s*\(/.test(sql.slice(tok.lastIndex)))
        out += `&lt;span class="tok-fn"&gt;${esc(t)}&lt;/span&gt;`;
      else out += `&lt;span class="tok-id"&gt;${esc(t)}&lt;/span&gt;`;
    } else out += `&lt;span class="tok-op"&gt;${esc(t)}&lt;/span&gt;`;
  }
  out += esc(sql.slice(last));
  return out;
}







// Widget autonome "bouton play + timing + recherche + tableau", pour
// dupliquer facilement une démo "Tester en live" avec une autre requête.
// mapRow convertit chaque ligne Arrow renvoyée par db.query en objet JS
// simple ; valueField est la colonne numérique utilisée pour la part (%)
// affichée dans la colonne "part". extraBar ajoute une 2e colonne barre
// (une autre couleur) sur un second champ numérique, pour comparer d'un
// coup d'oeil deux proportions (ex : part des parcelles vs part de la
// surface).
// `sql` peut être une chaîne, ou une fonction `(commune) =&gt; chaîne`. Avec
// `communeSearch: { placeholder, options }`, un champ commune avec
// autocomplétion (comboBox : valeur toujours "" ou une entrée exacte de
// `options`) apparaît À CÔTÉ de la barre de recherche, sous le bouton, une
// fois la démo lancée. Changer la commune relance la requête en direct
// (debounce), sans avoir à re-cliquer sur play -&gt; requête conditionnelle
// côté SQL, sans risque d'injecter une commune inexistante.
// La requête réellement exécutée est affichée (petit) sous le tableau.
function liveQueryDemo({
  sql,
  mapRow,
  valueField,
  searchFields,
  columns,
  header,
  width,
  valueFormat = frInt,
  searchPlaceholder = "🔍 Rechercher…",
  buttonLabel = "Tester en live",
  barColor = "#4758AB",
  extraBar = null,
  communeSearch = null,
  format = {},
  align = {}
}) {
  const btn = runLiveButton(buttonLabel);
  const resolveSql = (commune) =&gt; (typeof sql === "function" ? sql(commune) : sql);

  const communeField = communeSearch
    ? comboBox(communeSearch.options ?? [], { placeholder: communeSearch.placeholder })
    : null;
  const search = searchInput(searchPlaceholder);

  // Barre de recherche + champ commune : masqués tant que la démo n'a pas
  // tourné une première fois (rien à filtrer avant).
  const controls = html`&lt;div class="testlive-controls"&gt;${
    communeField
      ? html`&lt;label class="testlive-control"&gt;&lt;span&gt;Commune&lt;/span&gt;${communeField}&lt;/label&gt;`
      : ""
  }&lt;label class="testlive-control"&gt;${search}&lt;/label&gt;&lt;/div&gt;`;
  controls.style.display = "none";

  const statusBox = html`&lt;div&gt;&lt;/div&gt;`;
  const resultsBox = html`&lt;div&gt;&lt;/div&gt;`;
  const sqlBox = html`&lt;div&gt;&lt;/div&gt;`;
  let currentRows = null;
  let inFlight = false;
  let pending = null;

  function renderStatus(elapsed_ms, commune) {
    statusBox.replaceChildren(
      elapsed_ms == null
        ? html`&lt;p class="testlive-placeholder"&gt;Lancer la démo live.&lt;/p&gt;`
        : html`&lt;p class="testlive-timing"&gt;⏱️ Temps d'exécution : &lt;strong&gt;${elapsed_ms.toFixed(0)} ms&lt;/strong&gt; · ${totalInputRows.toLocaleString("fr-FR")} → ${currentRows.length} lignes${commune ? ` · commune : « ${commune} »` : ""}&lt;/p&gt;`
    );
  }

  function renderTable() {
    const q = search.value.trim().toLowerCase();
    const rows = !q
      ? currentRows
      : currentRows.filter((r) =&gt; searchFields.map((f) =&gt; r[f]).join(" ").toLowerCase().includes(q));
    const extraFormat = extraBar
      ? { [extraBar.key]: (v) =&gt; barCell(v, extraBar.color ?? barColor) }
      : {};
    resultsBox.replaceChildren(
      html`&lt;div class="testlive-results"&gt;${Inputs.table(rows, {
        columns,
        header,
        width,
        align: { [valueField]: "right", ...align },
        format: { [valueField]: valueFormat, part: (v) =&gt; barCell(v, barColor), ...extraFormat, ...format },
        layout: "fixed",
        rows: 10
      })}&lt;/div&gt;`
    );
  }

  // Sérialise les requêtes : si une nouvelle commune est demandée pendant
  // qu'une requête tourne, on garde seulement la dernière et on la lance à
  // la fin (évite les allers-retours d'affichage sur des clics rapides).
  async function run(commune) {
    if (inFlight) {
      pending = commune;
      return;
    }
    inFlight = true;
    statusBox.querySelector(".testlive-timing")?.classList.add("is-loading");
    const t0 = performance.now();
    try {
      const raw = await db.query(resolveSql(commune));
      const rows = Array.from(raw, mapRow);
      const total = d3.sum(rows, (d) =&gt; d[valueField]);
      let withParts = rows.map((d) =&gt; ({ ...d, part: total &gt; 0 ? d[valueField] / total : 0 }));
      if (extraBar) {
        const totalExtra = d3.sum(rows, (d) =&gt; d[extraBar.field]);
        withParts = withParts.map((d) =&gt; ({
          ...d,
          [extraBar.key]: totalExtra &gt; 0 ? d[extraBar.field] / totalExtra : 0
        }));
      }
      currentRows = withParts;
      search.value = "";
      renderStatus(performance.now() - t0, commune);
      renderTable();
      const codeEl = document.createElement("code");
      codeEl.innerHTML = sqlHighlight(resolveSql(commune).trim());
      sqlBox.replaceChildren(
        html`&lt;figure class="testlive-sql"&gt;&lt;figcaption&gt;SQL exécuté&lt;/figcaption&gt;&lt;pre&gt;${codeEl}&lt;/pre&gt;&lt;/figure&gt;`
      );
    } catch (e) {
      statusBox.replaceChildren(html`&lt;p class="testlive-placeholder"&gt;⚠️ Requête impossible : ${e.message}&lt;/p&gt;`);
    } finally {
      inFlight = false;
      if (pending !== null && pending !== commune) {
        const next = pending;
        pending = null;
        run(next);
      } else {
        pending = null;
      }
    }
  }

  renderStatus(null);

  search.addEventListener("input", renderTable);

  btn.addEventListener("input", () =&gt; {
    controls.style.display = "";
    // Passe le cadre en mode "lecture" : le bouton play cesse d'être centré
    // comme la vignette d'une vidéo, le contenu s'empile normalement.
    btn.closest(".testlive-widget")?.classList.add("is-running");
    run(communeField ? communeField.value : "");
  });

  if (communeField) {
    const debouncedRun = debounce((v) =&gt; run(v), 320);
    communeField.addEventListener("input", () =&gt; debouncedRun(communeField.value));
  }

  return html`&lt;div class="testlive-widget"&gt;${btn}${statusBox}${controls}${resultsBox}${sqlBox}&lt;/div&gt;`;
}







sqlTestLive = `
SELECT
    r.code_cultu,
    COALESCE(d.nom_culture, r.code_cultu) AS nom_culture,
    COALESCE(d.nom_chapitre, 'Non classé') AS nom_chapitre,
    COUNT(*) AS n
FROM read_parquet('${RPG_URL}') r
LEFT JOIN dico d ON r.code_cultu = d.code_culture
WHERE r.code_cultu IS NOT NULL
GROUP BY 1, 2, 3
ORDER BY n DESC
`







liveQueryDemo({
  sql: sqlTestLive,
  mapRow: (d) =&gt; ({
    code_cultu: d.code_cultu,
    nom_culture: d.nom_culture,
    nom_chapitre: d.nom_chapitre,
    n: Number(d.n)
  }),
  valueField: "n",
  searchFields: ["nom_culture", "nom_chapitre", "code_cultu"],
  columns: ["nom_culture", "nom_chapitre", "n", "part"],
  header: {
    nom_culture: "Culture",
    nom_chapitre: "Famille",
    n: "Parcelles",
    part: "Proportion"
  },
  width: { nom_culture: 200, nom_chapitre: 200, n: 90, part: 160 },
  searchPlaceholder: "🔍 Rechercher une culture ou une famille…"
})

Démo #3

// Même calcul que la démo précédente (part des surfaces par culture), mais
// avec un filtre commune appliqué CÔTÉ SQL : requête conditionnelle selon
// que le champ commune est vide ou non.
//   - vide      -&gt; exactement la requête de `test-live-surface.qmd`
//                  (tout le département)
//   - commune   -&gt; on ajoute `AND r.nom_officiel ILIKE '%…%'`
// Changer la commune (autocomplétion, valeur forcément valide) relance la
// requête en direct : le filtre coûte une vraie requête SQL, pas un tri
// client.
sqlTestLiveCommune = (commune) =&gt; `
SELECT
    r.code_cultu,
    COALESCE(d.nom_culture, r.code_cultu) AS nom_culture,
    COALESCE(d.nom_chapitre, 'Non classé') AS nom_chapitre,
    COUNT(*) AS n,
    SUM(r.area) / 10000 AS surface_ha
FROM read_parquet('${RPG_URL}') r
LEFT JOIN dico d ON r.code_cultu = d.code_culture
WHERE r.code_cultu IS NOT NULL${commune ? `
    AND r.nom_officiel ILIKE '%${commune.replace(/'/g, "''")}%'` : ""}
GROUP BY 1, 2, 3
ORDER BY surface_ha DESC
`







// Liste des communes présentes dans le RPG, pour l'autocomplétion du champ
// de filtre (comboBox : la valeur choisie est forcément l'une d'elles).
// DISTINCT direct sur le parquet : le fichier est déjà en cache (warmup),
// donc c'est quasi instantané et ça reste cohérent avec le `WHERE
// r.nom_officiel ILIKE …` de la requête.
communeNames = Array.from(
  await db.query(
    `SELECT DISTINCT nom_officiel FROM read_parquet('${RPG_URL}') WHERE nom_officiel IS NOT NULL ORDER BY 1`
  ),
  (d) =&gt; d.nom_officiel
)







liveQueryDemo({
  sql: sqlTestLiveCommune,
  communeSearch: {
    placeholder: "Toutes (taper pour filtrer)…",
    options: communeNames
  },
  mapRow: (d) =&gt; ({
    code_cultu: d.code_cultu,
    nom_culture: d.nom_culture,
    nom_chapitre: d.nom_chapitre,
    n: Number(d.n),
    surface_ha: Number(d.surface_ha)
  }),
  valueField: "surface_ha",
  extraBar: { field: "n", key: "part_n", color: "#4758AB" },
  searchFields: ["nom_culture", "nom_chapitre", "code_cultu"],
  columns: ["nom_culture", "nom_chapitre", "n", "part_n", "surface_ha", "part"],
  header: {
    nom_culture: "Culture",
    nom_chapitre: "Famille",
    n: "Parcelles",
    part_n: "Part parcelles",
    surface_ha: "Surface (ha)",
    part: "Part surface"
  },
  width: { nom_culture: 150, nom_chapitre: 150, n: 70, part_n: 120, surface_ha: 90, part: 120 },
  valueFormat: (v) =&gt; frNumber(v, 0),
  align: { n: "right" },
  format: { n: frInt },
  barColor: "#ec6842",
  searchPlaceholder: "🔍 Rechercher une culture ou une famille…"
})

Démo #4

// Résout code_cultu -&gt; {nom_culture, nom_chapitre, ...} pour les GeoJSON
// précalculés (data/communes/*.geojson, data/parcelles-full.geojson), qui ne
// stockent que le code (`k`) pour rester légers. Utilisé par
// demo/explorer-commune.qmd et demo/culture-highlight.qmd.
dicoByCode = new Map(dico.map((d) =&gt; [d.code_culture, d]))







// Import MapLibre partagé par les deux slides carte du deck
// (demo/explorer-commune.qmd et demo/culture-highlight.qmd), qui créent
// chacune leur propre instance de carte à partir de ce même module.
maplibregl = require("maplibre-gl@5")







// Géométries des parcelles précalculées par commune (voir
// scripts/generate_quarto_commune_data.py) : DuckDB-wasm dans le navigateur
// ne parvient pas à charger l'extension spatiale de façon fiable avec le
// DuckDBClient bundlé (version trop ancienne côté Observable), donc la
// reprojection Lambert-93 -&gt; WGS84 est faite une fois, au moment du rendu.
communeSlugs = fetch("data/communes/index.json").then((r) =&gt; r.json())







viewof communeSel = Inputs.select(Object.keys(communeSlugs).sort(), { label: "Commune", value: "Arras" })







familyColor = d3.scaleOrdinal(
  [...new Set(dico.map((d) =&gt; d.nom_chapitre))].sort(),
  d3.schemeTableau10.concat(d3.schemeSet3)
)







// Parcourt récursivement un tableau de coordonnées GeoJSON (Polygon ou
// MultiPolygon) pour calculer une bounding box, sans dépendance à turf.
function geojsonBounds(fc) {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  function visit(coords) {
    if (typeof coords[0] === "number") {
      const [x, y] = coords;
      if (x &lt; minX) minX = x;
      if (x &gt; maxX) maxX = x;
      if (y &lt; minY) minY = y;
      if (y &gt; maxY) maxY = y;
    } else {
      coords.forEach(visit);
    }
  }
  fc.features.forEach((f) =&gt; visit(f.geometry.coordinates));
  return [[minX, minY], [maxX, maxY]];
}









mapDiv = {
  const div = document.createElement("div");
  div.style.height = "440px";
  div.style.borderRadius = "8px";
  div.style.zIndex = "0";
  return div;
}







map = {
  const m = new maplibregl.Map({
    container: mapDiv,
    style: {
      version: 8,
      sources: {
        osm: {
          type: "raster",
          tiles: ["https://tile.openstreetmap.org/{z}/{x}/{y}.png"],
          tileSize: 256,
          attribution: "&copy; OpenStreetMap contributors"
        }
      },
      layers: [{ id: "osm", type: "raster", source: "osm" }]
    },
    center: [2.5, 50.4],
    zoom: 9
  });
  m.addControl(new maplibregl.NavigationControl());
  return m;
}







// Résolu une fois le style de base chargé : source + calques des parcelles,
// et le mouseover (popup) sur la couche de remplissage.
mapReady = new Promise((resolve) =&gt; {
  map.on("load", () =&gt; {
    map.addSource("parcels", { type: "geojson", data: { type: "FeatureCollection", features: [] } });
    map.addLayer({
      id: "parcels-fill",
      type: "fill",
      source: "parcels",
      paint: { "fill-color": ["get", "color"], "fill-opacity": 0.75 }
    });
    map.addLayer({
      id: "parcels-line",
      type: "line",
      source: "parcels",
      paint: { "line-color": "#20201d", "line-width": 0.4, "line-opacity": 0.6 }
    });

    const popup = new maplibregl.Popup({ closeButton: false });
    map.on("mousemove", "parcels-fill", (e) =&gt; {
      map.getCanvas().style.cursor = "pointer";
      const f = e.features[0];
      popup
        .setLngLat(e.lngLat)
        .setHTML(`&lt;strong&gt;${f.properties.nom_culture}&lt;/strong&gt;&lt;br&gt;${Number(f.properties.surface_ha).toFixed(2)} ha`)
        .addTo(map);
